// CSD_RATIONALE_BEGIN
// DIAGNOSIS OF RECENT FAILURES:
//
// Attempts 21–22 regressed badly (20–30% accuracy) because `RenderedEndsWith(generated, "<<")`
// is triggered by guidance-quoting text the model writes mid-reasoning:
//   "…wrap the formula in `<<int()!`"
//   "Note the prompt says<<int(form!"
// These false positives enter constrained mode at wrong context positions, generating junk
// content that CloseSpanWithinBudget cannot recover from within the remaining budget.
//
// Attempt 18 (BEST: 49% accuracy, 89.8% syntax) used `next == "<<"` exact equality, which
// accidentally filtered these false positives because guidance-quoting `<<` appears as
// multi-character tokens like `` `<<``, `<<int`, or with whitespace attachment, while the
// legitimate final-answer `<<` arrives as a standalone `<<` token. We cannot reproduce
// that exact check per instructions.
//
// KEY INSIGHT:
// With average 370 generated tokens per example and median 230, nearly all examples produce
// EOS before step 750. When the model EOS's naturally after writing <<formula>> in free text,
// the evaluator extracts that span. No constrained intervention needed. The cases requiring
// intervention are long-reasoning examples (>750 steps) where force-open at step 750
// provides the final constrained formula.
//
// STRATEGY: PURE FORCE-OPEN (no RenderedEndsWith detection)
// Phase 1 (steps 0–700): Free unconstrained generation. If EOS → break, use natural answer.
// Phase 2 (step ~700): If still running and not in span → force-open with OpenConstrainedSpan.
// Phase 3: Constrained generation loop with CloseSpanIfComplete + AdaptiveConstrainedStepWithPenalties.
//   Near-budget (≤60 steps remaining) or span too long → CloseSpanWithinBudget with full remaining budget.
//   EOS inside span → CloseSpanWithinBudget with remaining budget.
//
// WHY THIS FIXES THE PROBLEMS:
// - 6 unterminated spans (attempt 22): ALL caused by RenderedEndsWith false positives at step >150.
//   Pure force-open has ZERO false positives.
// - 1 malformed span (`{variable}` syntax): Force-open ensures constrained generation for the
//   final span, and penaltyTokens=["{"...] blocks curly braces.
// - 32 wrong-but-valid answers: inherently semantic; we maximize reasoning time (700 free steps)
//   so the model has full context before producing the formula.
//
// PARAMETERS (calibrated against best attempt 18):
//   prefixBudget = maxSteps - 200 = 700  (adequate reasoning time, 200 steps for constrained)
//   maxSpanTokens = 25 (generous for multi-operator formulas)
//   nearBudgetThreshold = 60 (ensure CloseSpanWithinBudget has enough to work with)
//   penaltyTokens = ["{", "}", "**", "^", "\\"] (block invalid formula characters)
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Branch A (outside span, steps < prefixBudget, UnconstrainedStep, non-EOS):
//   insideConstrainedOut stays false. Implication vacuously true.
//
// Branch B (outside span, steps < prefixBudget, EOS):
//   insideConstrainedOut stays false. Implication vacuously true.
//
// Branch C (outside span, steps >= prefixBudget, force-open, OpenConstrainedSpan):
//   OpenConstrainedSpan sets insideConstrainedOut := true, currentConstrainedOut := [].
//   parser.IsValidPrefix([]) holds by precondition parser.IsValidPrefix([]). Preserved.
//
// Branch D (inside span, remainingBudget <= nearBudgetThreshold OR spanTokens >= maxSpanTokens):
//   CloseSpanWithinBudget postcondition guarantees:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). Preserved.
//
// Branch E (inside span, CloseSpanIfComplete, closed=true):
//   insideConstrainedOut is set to false by helper (or span content cleared). Implication vacuously true.
//
// Branch F (inside span, CloseSpanIfComplete, closed=false, AdaptiveConstrained non-EOS):
//   AdaptiveConstrainedStepWithPenalties hard-masks to parser-valid next tokens plus EOS;
//   returns a token next where parser.IsValidPrefix(currentConstrainedOut + [next]) holds.
//   AppendConstrainedToken extends currentConstrainedOut by [next], preserving validity. Preserved.
//
// Branch G (inside span, AdaptiveConstrained returns EOS):
//   CloseSpanWithinBudget postcondition guarantees validity. Preserved.
//
// Invariant 2: |generated| <= |generatedPrefix| + steps
//
// Branch A (UnconstrainedStep, non-EOS): generated += [next] (+1), steps += 1. Preserved.
// Branch B (EOS): steps += 1, generated unchanged. Preserved.
// Branch C (OpenConstrainedSpan): appends exactly 1 token "<<" to generated, steps += 1.
//   |generated| = old+1 <= |gP| + (old_steps+1). Preserved.
// Branch D (CloseSpanWithinBudget with closeBudget = remainingBudget = maxSteps - steps_before):
//   |generated| grows by at most closeBudget; steps grows by closeBudget.
//   |generated| <= |gP| + steps_before + closeBudget = |gP| + maxSteps = |gP| + new_steps. Preserved.
// Branch E (CloseSpanIfComplete closed=true): appends at most 1 ">>" token, steps += 1. Preserved.
// Branch F (CloseSpanIfComplete closed=false [steps+1, no generated growth] +
//           AdaptiveConstrained [steps NOT incremented, no generated growth] +
//           AppendConstrainedToken [generated+1, steps NOT incremented]):
//   Net: generated grows by 1 (AppendConstrainedToken), steps grows by 1 (CloseSpanIfComplete).
//   |generated| <= |gP| + steps. Preserved.
// Branch G (EOS in span, CloseSpanWithinBudget with rem = maxSteps - steps_after_close_attempt):
//   rem <= maxSteps - steps_before - 1. steps grows by rem; generated grows by at most rem. Preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve step by step. After your full reasoning, write exactly one final answer as <<int(formula)>> using the exact variable names from the problem WITHOUT curly braces (write n not {n}, write p not {p}). Use only +, -, *, /, //, %. Never use ** or ^ or curly braces inside << >>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var prefixBudget: nat := if maxSteps > 250 then maxSteps - 200 else (if maxSteps > 100 then maxSteps - 50 else maxSteps / 2);
var penaltyTokens: seq<Token> := ["{", "}", "**", "^", "\\"];
var spanTokens: nat := 0;
var maxSpanTokens: nat := 25;
var nearBudgetThreshold: nat := 60;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var remainingBudget := maxSteps - steps;
    if steps >= prefixBudget && remainingBudget > nearBudgetThreshold {
      // Force open a constrained span for the final answer formula
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
      spanTokens := 0;
    } else {
      // Free unconstrained generation - no RenderedEndsWith check to avoid false positives
      // from guidance-quoting text like "write <<int(formula)>>" in reasoning
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
      }
    }
  } else {
    // Inside constrained span
    var remainingBudget := maxSteps - steps;

    // If near budget end or span too long: force close with all remaining budget
    if remainingBudget <= nearBudgetThreshold || spanTokens >= maxSpanTokens {
      if remainingBudget > 0 {
        var sg, si, sc := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainingBudget
        );
        generated := sg;
        insideConstrainedOut := si;
        currentConstrainedOut := sc;
        steps := steps + remainingBudget;
      }
      break;
    }

    // Try to close if complete (costs 1 step)
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      break;
    } else {
      // Generate next constrained token with penalties on invalid formula characters
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStepWithPenalties(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 2.0,
        penaltyTokens, 8.0,
        6, eosToken
      );
      if next == eosToken {
        // EOS inside span: force close with all remaining budget
        var rem := maxSteps - steps;
        if rem > 0 {
          var sg2, si2, sc2 := helpers.CloseSpanWithinBudget(
            lm, parser, prompt, generated, currentConstrainedOut, eosToken, rem
          );
          generated := sg2;
          insideConstrainedOut := si2;
          currentConstrainedOut := sc2;
          steps := steps + rem;
        }
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
        spanTokens := spanTokens + 1;
      }
    }
  }
}

cost := steps;

